import api from './api';

// Contactos para el formulario de visitas (ADMIN y GUARDIA): [{ id, username }]
export const getUsers = async () => {
  const { data } = await api.get('/users/contacts');
  return data;
};

// Listado paginado de usuarios (ADMIN y RRHH): { data, meta }
export const listUsers = async (page = 1, limit = 10) => {
  const { data } = await api.get('/users', { params: { page, limit } });
  return data;
};

// Editar usuario: { username?, password?, profileId? } (solo lo que se envía se actualiza)
export const updateUser = async (id, user) => {
  const { data } = await api.put(`/users/${id}`, user);
  return data;
};

// Eliminar usuario (soft delete: queda deshabilitado y pierde el acceso)
export const deleteUser = async (id) => {
  const { data } = await api.delete(`/users/${id}`);
  return data;
};

// Crear usuario (ADMIN y RRHH): { username, password, profileId }
export const registerUser = async (user) => {
  const { data } = await api.post('/auth/register', user);
  return data;
};
